#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    vector<long long> d(n);
    for (int i = 0; i < n; i++) cin >> d[i];
    long long total = k + 1;
    for (int i = 1; i < n; i++) {
        long long extendCost = d[i] - d[i - 1];
        long long newCost = k + 1;
        total += min(extendCost, newCost);
    }
    cout << total << '\n';
    return 0;
}

