        }
        long totalCost = k + 1;
        for (int i = 1; i < n; i++) {
            long extendCost = d[i] - d[i - 1];
            long newCost = 1 + k;
            totalCost += Math.min(extendCost, newCost);
        }
        System.out.println(totalCost);
